// Parses a level's character rows into tiles, items, hazards and platforms.
// The levels themselves are generated by scripts/build-levels.py (levels.ts).
export type Tile = '#' | '=' | ' ';
export type Mover = { x: number; w: number; baseY: number; i: number };
export type HazardKind = 'S' | 'T' | 'N';

export function parse(rows: string[]) {
  const h = rows.length;
  const w = Math.max(...rows.map((r) => r.length));
  const tiles: Tile[][] = [];
  const items: { x: number; y: number; kind: 'o' | '^' | 'C' | 'F' }[] = [];
  const hazards: { x: number; y: number; kind: HazardKind; i: number }[] = [];
  const movers: Mover[] = [];
  let spawn = { x: 0, y: 0 };
  for (let y = 0; y < h; y++) {
    tiles[y] = [];
    for (let x = 0; x < w; x++) {
      const c = rows[y][x] ?? ' ';
      tiles[y][x] = c === '#' || c === '=' ? c : ' ';
      if (c === 'P') spawn = { x, y };
      if (c === 'o' || c === '^' || c === 'C' || c === 'F') items.push({ x, y, kind: c });
      if (c === 'S' || c === 'T' || c === 'N') hazards.push({ x, y, kind: c, i: hazards.length });
      // A run of M tiles is one rate-line platform.
      if (c === 'M' && rows[y][x - 1] !== 'M') {
        let n = 0;
        while (rows[y][x + n] === 'M') n++;
        movers.push({ x, w: n, baseY: y, i: movers.length });
      }
    }
  }
  return { w, h, tiles, items, hazards, spawn, movers };
}
